// Regenerates functions/ai/guide.mjs from dev/ai-markdown-guide.md.
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const sourcePath = fileURLToPath(
  new URL('./ai-markdown-guide.md', import.meta.url),
);
const outputPath = fileURLToPath(
  new URL('../functions/ai/guide.mjs', import.meta.url),
);

const markdown = await readFile(sourcePath, 'utf8');
const header =
  '// Generated by dev/build-ai-guide.mjs from docs/ai-markdown-guide.md. Do not edit by hand.\n';
await writeFile(
  outputPath,
  `${header}export const AI_MARKDOWN_GUIDE = ${JSON.stringify(markdown)};\n`,
);
console.log(`wrote guide (${markdown.length} chars) -> ${outputPath}`);